def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    player_count = 1 + len(alive)
    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < player_count

    prev_bids = []
    desperate_opp = False
    rich_opp_pressure = 0.0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0)
            prev_bids.append(bid)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_opp = True
            if opp.get('budget', 0) > budget and bid > rich_opp_pressure:
                rich_opp_pressure = bid

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2
    if scarcity:
        urgency += 1
    if desperate_opp:
        urgency += 1

    if prev_bids:
        top_prev = max(prev_bids)
    else:
        top_prev = 0

    if urgency >= 5:
        target = max(0.92 * DAILY_SALARY, top_prev + 2.0)
    elif urgency >= 3:
        target = max(0.72 * DAILY_SALARY, top_prev + 1.0)
    elif urgency >= 2:
        target = max(0.55 * DAILY_SALARY, min(top_prev + 0.5, 0.78 * DAILY_SALARY))
    else:
        if scarcity:
            target = max(0.42 * DAILY_SALARY, min(top_prev + 0.5, 0.62 * DAILY_SALARY))
        else:
            target = 0.28 * DAILY_SALARY

    if rich_opp_pressure >= 0.85 * DAILY_SALARY and urgency <= 2:
        target = min(target, 0.38 * DAILY_SALARY)

    days_left_est = max(1, 10 - int(day_context['day']) + 1)
    reserve_floor = max(0.0, (days_left_est - 1) * DAILY_SALARY * 0.18)
    affordable = max(0.0, budget - reserve_floor)

    bid = min(budget, affordable if affordable > 0 else budget, target)

    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(bid, 0.9 * DAILY_SALARY, top_prev + 1.5 if prev_bids else 0))

    if bid < 0:
        bid = 0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opponents.append(o)

    # Baseline: target just enough to meet our requirement with some buffer.
    # Convert to a bid within our budget.
    # If supply is tight, we must bid more.
    tightness = 0.0
    if supply <= float(WATER_REQ):
        tightness = 1.0
    else:
        # supply in [15,25] typically; map to [0,1]
        tightness = (float(MAX_SUPPLY) - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
        if tightness < 0.0:
            tightness = 0.0
        if tightness > 1.0:
            tightness = 1.0

    # Read yesterday bids from previous_trace for immediate reaction.
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # If opponents were aggressive yesterday, adjust upward.
    # We do not know their current hidden bids; we use their last bid as a proxy.
    aggressive_threshold = DAILY_SALARY * 0.85
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If someone was bidding extremely high, assume scarcity/low hp and bid to secure.
        if highest_prev_bid >= aggressive_threshold:
            # If our hp is low, we must prioritize water.
            if my_status.get('hp', 0) <= 2:
                target = DAILY_SALARY * (0.85 + 0.1 * tightness)
            else:
                target = DAILY_SALARY * (0.65 + 0.15 * tightness)
            # Ensure we don't blindly overpay: bid just above their likely level when possible.
            # Add a small increment to beat them.
            bid = max(target, highest_prev_bid + 1.0)
        else:
            # They were not too aggressive: bid moderately, enough to meet our needs.
            # Use their max as a soft cap.
            soft = max(DAILY_SALARY * (0.45 + 0.2 * tightness), highest_prev_bid * 0.9 + 0.5)
            bid = soft
    else:
        # No trace info: bid based on our hp and supply tightness.
        if my_status.get('hp', 0) <= 2:
            bid = DAILY_SALARY * (0.75 + 0.2 * tightness)
        else:
            bid = DAILY_SALARY * (0.5 + 0.15 * tightness)

    # Convert bid to a safe amount within our budget.
    budget = float(my_status.get('budget', 0.0))
    if budget <= 0.0:
        return 0.0

    # Also avoid bidding more than needed for our requirement when supply is ample.
    # Approximate: if supply is high, we can bid lower.
    # Scale with how many requirements fit in expected supply.
    # Note: no list indexing required.
    expected_fit = supply / float(WATER_REQ)
    if expected_fit >= 2.0:
        bid *= 0.75
    elif expected_fit >= 1.5:
        bid *= 0.9

    # Final clamp.
    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    # Keep some reserve for later days.
    # If we have many no-water days, we should be more willing to spend.
    no_water_days = int(my_status.get('no_water_days', 0))
    if no_water_days >= 2:
        reserve_frac = 0.05
    else:
        reserve_frac = 0.15
    max_affordable = budget * (1.0 - reserve_frac)
    if bid > max_affordable:
        bid = max_affordable

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MY_HP = my_status['hp']
    BUDGET = my_status['budget']
    ALIVE_OPPONENTS = [o for o in opponents_status.values() if o['alive']]
    if not ALIVE_OPPONENTS:
        return min(BUDGET, DAILY_SALARY * 0.4)
    if MY_HP <= 2:
        return min(BUDGET, DAILY_SALARY * 0.9)
    elif MY_HP <= 3:
        return min(BUDGET, DAILY_SALARY * 0.7)
    else:
        return min(BUDGET, DAILY_SALARY * 0.45)
